@gene('v3', "option kinds worth listing this pass: only those this turn's rule (or shopping, cast-ahead) can use; dash gate cached at turn start", parents=["v3"])
def consider(k: Num) -> Bool:
    r = RULE
    if k == PICK:
        return True
    if k == BUY or k == BUY_LOCK:
        return r >= 2 and can_shop() and at_spawn()
    if shop_pending():
        return False
